import{_ as e,o as i,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Crimson/SeaStore 2021-03-10","description":"","frontmatter":{"title":"Ceph Crimson/SeaStore 2021-03-10","date":"2021-03-10T00:00:00.000Z","updated":"2021-03-10T00:00:00.000Z","tags":["Ceph","分布式存储","单元测试","垃圾收集","性能优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Crimson_SeaStore_2021-03-10.md","filePath":"posts/2021/Ceph_Crimson_SeaStore_2021-03-10.md","lastUpdated":1780459816000}'),r={name:"posts/2021/Ceph_Crimson_SeaStore_2021-03-10.md"};function o(n,l,s,u,h,p){return i(),a("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><p><strong>上周工作回顾</strong>：</p><ul><li>完成了一些清理工作，并继续处理客户端请求序列化测试。</li><li>与Shihan和Redec讨论了启动工作，并改进了Alien Store性能。</li><li>调试了NPD的段错误报告，发现由垃圾收集引起的RB树混乱，并修复了相关bug。</li><li>开发了一种方法来重现Chutney观察到的行为，修复了LBA管理器的小bug。</li><li>测试了PG流水线并行性PR，并阅读了关于Sistor的源代码和文档。</li><li>解决了Honor 3中的问题，并支持了存储中的多设备。</li></ul></li><li><p><strong>本周计划</strong>：</p><ul><li>继续测试PG流水线并行性PR，并阅读Sistor相关文档。</li><li>增加对TL管理器的单元测试，特别是对Ethel Tree Node Manager接口的全面支持。</li><li>修改单元测试以支持两种后端运行，以更好地理解问题所在。</li></ul></li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ul><li><p><strong>单元测试的改进</strong>：</p><ul><li>讨论了增加单元测试的必要性，尤其是对Ethel Tree Node Manager接口的全面测试。</li><li>讨论了如何修改单元测试以支持两种后端运行，以确保测试的全面性和可靠性。</li></ul></li><li><p><strong>垃圾收集器和段错误问题</strong>：</p><ul><li>讨论了垃圾收集器引起的问题，以及如何通过增加单元测试来避免类似问题。</li><li>讨论了段错误问题的根本原因，并提出了增加超时机制的解决方案。</li></ul></li></ul><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li><p><strong>增加单元测试</strong>：</p><ul><li>决定增加对TL管理器和Ethel Tree Node Manager接口的单元测试，以确保代码的稳定性和可靠性。</li><li>决定修改单元测试以支持两种后端运行，以更好地理解问题所在。</li></ul></li><li><p><strong>增加超时机制</strong>：</p><ul><li>决定在脚本中增加超时机制，以防止单元测试无限期运行。</li></ul></li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><p><strong>实施单元测试改进</strong>：</p><ul><li>增加对TL管理器和Ethel Tree Node Manager接口的单元测试。</li><li>修改单元测试以支持两种后端运行。</li></ul></li><li><p><strong>增加超时机制</strong>：</p><ul><li>在脚本中增加超时机制，以防止单元测试无限期运行。</li></ul></li><li><p><strong>继续调试和修复问题</strong>：</p><ul><li>继续调试NPD的段错误问题，并修复垃圾收集器引起的问题。</li><li>继续测试PG流水线并行性PR，并阅读Sistor相关文档。</li></ul></li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>讨论了Ethel Tree代码的复杂性，并提出了增加单元测试的必要性。</li><li>讨论了垃圾收集器和段错误问题的根本原因，并提出了增加超时机制的解决方案。</li></ul>',11)])])}const c=e(r,[["render",o]]);export{_ as __pageData,c as default};
